package com.wms.controller;
import com.wms.dto.StockOutRequest; import com.wms.harness.Harness; import com.wms.model.entity.Inventory; import com.wms.model.entity.InventoryTransaction; import com.wms.repository.InventoryRepository; import com.wms.repository.InventoryTransactionRepository; import com.wms.service.InventoryService; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.time.LocalDateTime; import java.time.format.DateTimeFormatter; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class ReportControllerIntegrationTest {
 @Autowired private ReportController reports; @Autowired private InventoryService inventory; @Autowired private InventoryTransactionRepository transactions; @Autowired private InventoryRepository inventories;
 @Test void inOutSummaryRebuildsHistoricalPeriodInsteadOfReadingCurrentInventory(){Harness.asAdmin(()->{LocalDate period=LocalDate.now().minusMonths(2).withDayOfMonth(1);InventoryTransaction seed=transactions.findRecentDetailed().stream().filter(t->"ITEM-001".equals(t.getItem().getCode())&&"in".equals(t.getTransactionType())).findFirst().orElseThrow();seed.setTransactionAt(period.plusDays(2).atStartOfDay());transactions.saveAndFlush(seed);inventory.stockOut(new StockOutRequest("ITEM-001",new BigDecimal("10"),new BigDecimal("99"),1L,"A-01-01",null,"本月后出库"));List<Map<String,Object>> rows=reports.inOutSummary(period.format(DateTimeFormatter.ofPattern("yyyy-MM"))).data();Map<String,Object> row=rows.stream().filter(x->"ITEM-001".equals(x.get("itemCode"))).findFirst().orElseThrow();assertEquals(0,new BigDecimal("100").compareTo((BigDecimal)row.get("inQuantity")));assertEquals(0,BigDecimal.ZERO.compareTo((BigDecimal)row.get("outQuantity")));assertEquals(0,new BigDecimal("100").compareTo((BigDecimal)row.get("endingQuantity")));BigDecimal live=inventories.findAllDetailed().stream().filter(i->"ITEM-001".equals(i.getItem().getCode())).map(Inventory::getQuantity).reduce(BigDecimal.ZERO,BigDecimal::add);assertEquals(0,new BigDecimal("90").compareTo(live));});}
 @Test void dashboardSeparatesSalesFromAllOutboundCostAndCountsUniqueItems(){Harness.asAdmin(()->{inventory.stockOut(new StockOutRequest("ITEM-001",new BigDecimal("2"),new BigDecimal("99"),1L,"A-01-01",null,"销售"));Map<String,Object> data=reports.dashboard().data();assertEquals(0,new BigDecimal("198.00").compareTo((BigDecimal)data.get("todaySalesAmount")));assertEquals(0,new BigDecimal("31.00").compareTo((BigDecimal)data.get("todayOutboundAmount")));long expected=inventories.findAllDetailed().stream().filter(i->i.getQuantity().signum()>0).map(i->i.getItem().getId()).distinct().count();assertEquals(expected,((Number)data.get("stockItemCount")).longValue());});}
 @Test void inventoryAgeConsumesOldestLayersWithinTheSameBatch(){Harness.asAdmin(()->{InventoryTransaction seed=transactions.findRecentDetailed().stream().filter(t->"ITEM-001".equals(t.getItem().getCode())&&"in".equals(t.getTransactionType())).findFirst().orElseThrow();seed.setTransactionAt(LocalDateTime.now().minusDays(100));transactions.saveAndFlush(seed);inventory.stockOut(new StockOutRequest("ITEM-001",new BigDecimal("80"),new BigDecimal("99"),1L,"A-01-01",null,"消耗旧层"));inventory.stockIn(new com.wms.dto.StockInRequest("ITEM-001",new BigDecimal("20"),new BigDecimal("15.50"),1L,"A-01-01",null,"补入新层"));Map<String,Object> row=reports.inventoryAge().data().stream().filter(x->"ITEM-001".equals(x.get("itemCode"))).findFirst().orElseThrow();assertEquals(50L,((Number)row.get("ageDays")).longValue());assertEquals("30-60",row.get("bucket"));});}
}
